/**
 * 1年前の今日、あやとがどこで何を配信していたか。
 * python/build_on_this_day.py が BigQuery から作る。**手で編集しない。**
 *
 * 月日(MM-DD)で引くと、その日にあった配信が新しい順に出る。
 * 1日につき1本だけ。その日いちばんコメントが多かった配信を代表にしてある。
 *
 * 静的書き出しなので、今日が何日かはビルド時に決められない。
 * 引くのは画面が出てから（`site/lib/nightly.ts` の `jstNow`）。
 */

export type PastStream = {
  /** 配信のあった日。JST の YYYY-MM-DD */
  d: string;
  /** YouTube の動画ID */
  v: string;
  /** 配信のタイトル。引用なのでそのまま出す（絵文字が入っていてもよい） */
  t: string;
  /** そのとき居た街。街まで分からない日は国の名前 */
  p: string;
  /** 国の slug。国旗を出すのに使う */
  c: string;
  /** その配信に付いたコメントの数 */
  n: number;
  /**
   * コメントがいちばん重なったところ。配信のはじめから何秒か。
   * 分かっている配信にしか無い（`content/streamPeaks.ts`）。
   * 3時間の頭から出しても誰も再生しないので、あるならここから開く。
   */
  k?: number;
};

